function PouringLadleSpoutLinerMaker.init() PouringLadleSpoutLinerMaker.ironStock=12; PouringLadleSpoutLinerMaker.bronzeStock=10; PouringLadleSpoutLinerMaker.woodStock=14; PouringLadleSpoutLinerMaker.leatherStock=10; PouringLadleSpoutLinerMaker.silverStock=8; PouringLadleSpoutLinerMaker.goldStock=6; PouringLadleSpoutLinerMaker.jewelStock=4; PouringLadleSpoutLinerMaker.pearlStock=4; PouringLadleSpoutLinerMaker.productStock={}; PouringLadleSpoutLinerMaker.buildings={}; PouringLadleSpoutLinerMaker.maker=nil; PouringLadleSpoutLinerMaker.activeMaking={}; PouringLadleSpoutLinerMaker.totalProducts=0; PouringLadleSpoutLinerMaker.dayTimer=0; print("[PouringLadleSpoutLinerMaker] Royal Pouring Ladle Spout Liner Maker System initialized (6 products, 4 buildings)") end
function PouringLadleSpoutLinerMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; PouringLadleSpoutLinerMaker.maker={name=n or ("Oblogar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Oblogar najet: %s (spretnost: %d)",PouringLadleSpoutLinerMaker.maker.name,s),"success") end; return true end
function PouringLadleSpoutLinerMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function PouringLadleSpoutLinerMaker.build(id) local ok,e=PouringLadleSpoutLinerMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(PouringLadleSpoutLinerMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function PouringLadleSpoutLinerMaker.getQualityBonus() local b=0; for _,bd in ipairs(PouringLadleSpoutLinerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function PouringLadleSpoutLinerMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and PouringLadleSpoutLinerMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and PouringLadleSpoutLinerMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and PouringLadleSpoutLinerMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and PouringLadleSpoutLinerMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and PouringLadleSpoutLinerMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and PouringLadleSpoutLinerMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and PouringLadleSpoutLinerMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and PouringLadleSpoutLinerMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #PouringLadleSpoutLinerMaker.buildings==0 then return false,"Potrebna oblozna delavnica" end; if not PouringLadleSpoutLinerMaker.maker then return false,"Potreben oblogar" end; return true end
function PouringLadleSpoutLinerMaker.make(pt,qty) qty=qty or 1; local ok,e=PouringLadleSpoutLinerMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then PouringLadleSpoutLinerMaker.ironStock=PouringLadleSpoutLinerMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then PouringLadleSpoutLinerMaker.bronzeStock=PouringLadleSpoutLinerMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then PouringLadleSpoutLinerMaker.woodStock=PouringLadleSpoutLinerMaker.woodStock-d.woodCost*qty end; if d.leatherCost then PouringLadleSpoutLinerMaker.leatherStock=PouringLadleSpoutLinerMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then PouringLadleSpoutLinerMaker.silverStock=PouringLadleSpoutLinerMaker.silverStock-d.silverCost*qty end; if d.goldCost then PouringLadleSpoutLinerMaker.goldStock=PouringLadleSpoutLinerMaker.goldStock-d.goldCost*qty end; if d.jewelCost then PouringLadleSpoutLinerMaker.jewelStock=PouringLadleSpoutLinerMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then PouringLadleSpoutLinerMaker.pearlStock=PouringLadleSpoutLinerMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if PouringLadleSpoutLinerMaker.maker then t=math.max(1,t-math.floor(PouringLadleSpoutLinerMaker.maker.skill/13)) end; table.insert(PouringLadleSpoutLinerMaker.activeMaking,{id="pouringladlespoutliner_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function PouringLadleSpoutLinerMaker.completeMaking(m) local q=1.0+(PouringLadleSpoutLinerMaker.getQualityBonus()/100); if PouringLadleSpoutLinerMaker.maker then q=q+(PouringLadleSpoutLinerMaker.maker.skill/140) end; q=math.min(2.5,q); PouringLadleSpoutLinerMaker.productStock[m.productType]=(PouringLadleSpoutLinerMaker.productStock[m.productType] or 0)+m.quantity; PouringLadleSpoutLinerMaker.totalProducts=PouringLadleSpoutLinerMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if PouringLadleSpoutLinerMaker.maker then PouringLadleSpoutLinerMaker.maker.itemsMade=PouringLadleSpoutLinerMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then PouringLadleSpoutLinerMaker.maker.skill=math.min(100,PouringLadleSpoutLinerMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Obloga izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"pouringladlespoutliner.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function PouringLadleSpoutLinerMaker.update(dt) if not _G.state then return end; PouringLadleSpoutLinerMaker.dayTimer=PouringLadleSpoutLinerMaker.dayTimer+dt; if PouringLadleSpoutLinerMaker.dayTimer>=30 then PouringLadleSpoutLinerMaker.dayTimer=0; for i=#PouringLadleSpoutLinerMaker.activeMaking,1,-1 do local m=PouringLadleSpoutLinerMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then PouringLadleSpoutLinerMaker.completeMaking(m); table.remove(PouringLadleSpoutLinerMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(PouringLadleSpoutLinerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if PouringLadleSpoutLinerMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function PouringLadleSpoutLinerMaker.getStats() return {ironStock=PouringLadleSpoutLinerMaker.ironStock,bronzeStock=PouringLadleSpoutLinerMaker.bronzeStock,woodStock=PouringLadleSpoutLinerMaker.woodStock,leatherStock=PouringLadleSpoutLinerMaker.leatherStock,silverStock=PouringLadleSpoutLinerMaker.silverStock,goldStock=PouringLadleSpoutLinerMaker.goldStock,jewelStock=PouringLadleSpoutLinerMaker.jewelStock,pearlStock=PouringLadleSpoutLinerMaker.pearlStock,productStock=PouringLadleSpoutLinerMaker.productStock,numBuildings=#PouringLadleSpoutLinerMaker.buildings,hasMaker=PouringLadleSpoutLinerMaker.maker~=nil,makerName=PouringLadleSpoutLinerMaker.maker and PouringLadleSpoutLinerMaker.maker.name or "—",makerSkill=PouringLadleSpoutLinerMaker.maker and PouringLadleSpoutLinerMaker.maker.skill or 0,activeMaking=#PouringLadleSpoutLinerMaker.activeMaking,totalProducts=PouringLadleSpoutLinerMaker.totalProducts} end
